def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (0,5) and (i,j) not in seen:
                c=g[i][j]; stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                out.append((c,cells))
    return out
